<script setup lang="ts">
import { ref, onMounted, computed } from 'vue';
import { useRoute } from 'vue-router';
import type { Alert, Shop, Run } from '../../../shared/contracts.js';
import { get, patch } from '../api/client';
import { useLatest } from '../composables/useLatest';
import { useFeedback } from '../composables/useFeedback';
import { money, discount, dateTime } from '../lib/format';
import PageHeader from '../components/PageHeader.vue';
import StatCards from '../components/StatCards.vue';
import StatusTag from '../components/StatusTag.vue';
import ErrorBanner from '../components/ErrorBanner.vue';
const route = useRoute();
const alerts = ref<Alert[]>([]), shops = ref<Shop[]>([]), runs = ref<Run[]>([]), selected = ref<Alert[]>([]);
const state = ref(''), shopId = ref(''), runId = ref(typeof route.query.runId === 'string' ? route.query.runId : '');
const editing = ref<Alert | null>(null), note = ref(''), editState = ref<Alert['state']>('pending');
const resource = useLatest(), { busy, error, act } = useFeedback();
const counts = computed(() => ({ pending: alerts.value.filter(alert => alert.state === 'pending').length, confirmed: alerts.value.filter(alert => alert.state === 'confirmed').length, resolved: alerts.value.filter(alert => alert.state === 'resolved').length }));
function refresh() { const params = new URLSearchParams({ state: state.value, shopId: shopId.value, runId: runId.value }); return resource.load(() => get<{ alerts: Alert[] }>(`/alerts?${params}`), result => { alerts.value = result.alerts; selected.value = []; }); }
function open(alert: Alert) { editing.value = alert; note.value = alert.note; editState.value = alert.state; error.value = ''; }
async function save() { if (!editing.value) return; await act(async () => { await patch(`/alerts/${editing.value!.id}`, { state: editState.value, note: note.value }); editing.value = null; await refresh(); }, '预警处理状态与备注已保存'); }
async function batch(state: Alert['state']) { const snapshot = [...selected.value]; await act(async () => { for (const alert of snapshot) await patch(`/alerts/${alert.id}`, { state }); await refresh(); }, `已更新 ${snapshot.length} 条预警`); }
onMounted(() => { void refresh(); void act(async () => { const [a, b] = await Promise.all([get<{ shops: Shop[] }>('/shops'), get<{ runs: Run[] }>('/runs')]); shops.value = a.shops; runs.value = b.runs; }); });
</script>
<template><div><PageHeader title="预警记录" description="每次执行独立保存异常证据。确认或处理不会自动加入白名单，也不会抑制下一次预警。"><el-button :loading="resource.loading.value" @click="refresh">刷新记录</el-button></PageHeader><ErrorBanner :message="error || resource.error.value" /><StatCards :items="[{ label: '当前查询预警', value: alerts.length, hint: '接口最多返回最近 1,000 条' }, { label: '待处理', value: counts.pending, tone: 'warning' }, { label: '已确认', value: counts.confirmed, tone: 'primary' }, { label: '已处理', value: counts.resolved }]" /><section class="panel"><div class="toolbar"><el-select v-model="state" clearable placeholder="全部处理状态" style="width:160px" @change="refresh"><el-option value="pending" label="待处理" /><el-option value="confirmed" label="已确认" /><el-option value="resolved" label="已处理" /></el-select><el-select v-model="shopId" clearable placeholder="全部店铺" style="width:190px" @change="refresh"><el-option v-for="shop in shops" :key="shop.id" :value="shop.id" :label="shop.name" /></el-select><el-select v-model="runId" filterable clearable placeholder="全部执行批次" style="width:290px" @change="refresh"><el-option v-for="run in runs" :key="run.id" :value="run.id" :label="`${run.shopName} / ${dateTime(run.createdAt)}`" /></el-select><span class="spacer" /><span class="muted">已选 {{ selected.length }}</span><el-button :disabled="!selected.length || busy" @click="batch('confirmed')">批量确认</el-button><el-button type="primary" plain :disabled="!selected.length || busy" @click="batch('resolved')">批量处理</el-button></div><el-table :data="alerts" v-loading="resource.loading.value" row-key="id" max-height="650" empty-text="暂无符合条件的预警记录。完成采集与规则评估后，异常会显示在这里。" @selection-change="(rows: Alert[]) => selected = rows"><el-table-column type="selection" width="48" /><el-table-column label="商品 / 店铺" min-width="280"><template #default="{ row }"><a class="cell-title" @click="open(row)">{{ row.title }}</a><div class="cell-sub">{{ row.shopName }} · {{ row.productId }}</div><div class="cell-sub">{{ row.specs }} · SKU {{ row.skuId || '商品级' }}</div></template></el-table-column><el-table-column label="后台 / 优惠前 / 优惠后" min-width="170"><template #default="{ row }"><div>{{ money(row.backendPrice) }} / {{ money(row.before) }}</div><strong style="color:#0e918b">{{ money(row.after) }}</strong> <span class="muted">{{ discount(row.discount) }}</span></template></el-table-column><el-table-column label="触发原因" min-width="230"><template #default="{ row }"><div v-for="reason in row.reasons" :key="reason" class="reason-line">{{ reason }}</div></template></el-table-column><el-table-column label="处理状态" width="110"><template #default="{ row }"><StatusTag :value="row.state" /></template></el-table-column><el-table-column label="备注" min-width="170"><template #default="{ row }">{{ row.note || '—' }}</template></el-table-column><el-table-column label="触发时间" width="180"><template #default="{ row }">{{ dateTime(row.createdAt) }}</template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{ row }"><el-button text type="primary" @click="open(row)">处理详情</el-button></template></el-table-column></el-table></section><el-dialog :model-value="!!editing" title="预警详情与处理" width="700px" @close="editing = null"><template v-if="editing"><ErrorBanner :message="error" /><h3 style="font-size:16px">{{ editing.title }}</h3><p class="muted">{{ editing.shopName }} · 商品 {{ editing.productId }} · SKU {{ editing.skuId || '商品级' }}</p><p class="muted">{{ editing.specs }} · {{ dateTime(editing.createdAt) }}</p><div class="inline-metrics pill-note"><span>后台 {{ money(editing.backendPrice) }}</span><span>优惠前 {{ money(editing.before) }}</span><span>优惠后 {{ money(editing.after) }}</span><span>{{ discount(editing.discount) }}</span></div><ul><li v-for="reason in editing.reasons" :key="reason">{{ reason }}</li></ul><p class="muted">执行 ID：{{ editing.runId }}<br>任务 ID：{{ editing.taskId || '临时采集' }}</p><el-form label-position="top"><el-form-item label="处理状态"><el-radio-group v-model="editState"><el-radio-button value="pending">待处理</el-radio-button><el-radio-button value="confirmed">已确认</el-radio-button><el-radio-button value="resolved">已处理</el-radio-button></el-radio-group></el-form-item><el-form-item label="处理备注"><el-input v-model="note" type="textarea" :rows="4" placeholder="记录排查结论与处理动作" /></el-form-item></el-form><router-link :to="{ path: '/prices', state: { priceQuery: { view: 'sku', runId: editing.runId } } }">查询该执行价格证据 →</router-link></template><template #footer><el-button @click="editing = null">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存处理记录</el-button></template></el-dialog></div></template>
